        Objects.requireNonNull(arr, NULL_ARRAY_MSG);
        T[] copy = arr.clone();
        sort(copy);
        return copy;
    }

    public static <T> T[] sortedCopy(T[] arr, Comparator<? super T> comparator) {
        Objects.requireNonNull(arr, NULL_ARRAY_MSG);
        Objects.requireNonNull(comparator, NULL_COMPARATOR_MSG);
        T[] copy = arr.clone();
        sort(copy, comparator);
        return copy;
