        Objects.requireNonNull(list, NULL_LIST_MSG);
        Objects.requireNonNull(comparator, NULL_COMPARATOR_MSG);
        sortCore(0, list.size(),
            (i, j) -> comparator.compare(list.get(i), list.get(j)) > 0,
            (i, j) -> Collections.swap(list, i, j));
    }

