        List<T> copy = new ArrayList<>(list);
        sort(copy, comparator);
        return copy;
    }

    public static void main(String[] args) {
        int[] arr = {12, 11, 13, 5, 6};
        System.out.println(Arrays.toString(sortedCopy(arr)));
    }
}

